def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    adj = [[] for _ in range(N + 1)]
    index = 1
    for _ in range(N - 1):
        u = int(data[index])
        v = int(data[index + 1])
        adj[u].append(v)
        adj[v].append(u)
        index += 2

    if len(adj[1]) == 1:
        print(1)
        return

    ops = [0] * (N + 1)
    stack = [(1, None, False)]
    while stack:
        node, p, visited = stack.pop()
        if not visited:
            stack.append((node, p, True))
            for v in reversed(adj[node]):
                if v != p:
                    stack.append((v, node, False))
        else:
            total = 0
            for v in adj[node]:
                if v != p:
                    total += ops[v]
            ops[node] = total + 1

    min_ops = float('inf')
    for child in adj[1]:
        min_ops = min(min_ops, ops[child])
    print(min_ops + 1)

