    distinct_count = 0
    output = []
    idx = 1
    for _ in range(Q):
        query_type = data[idx]
        if query_type == '1' or query_type == '2':
            x = int(data[idx + 1])
            if query_type == '1':
                prev_count = count_map.get(x, 0)
                if prev_count == 0:
                    distinct_count += 1
                count_map[x] = prev_count + 1
                idx += 2
            else:
                prev_count = count_map[x]
                if prev_count == 1:
                    distinct_count -= 1
                count_map[x] = prev_count - 1
                idx += 2
        else:
            output.append(str(distinct_count))
            idx += 1
    print('\n'.join(output))

