import sys

def main():
    n, m = map(int, sys.stdin.readline().split())
    existing = [tuple(map(int, sys.stdin.readline().split())) for _ in range(m)]

    s = set()
    directions = [(2,1), (1,2), (-1,2), (-2,1), (-2,-1), (-1,-2), (1,-2), (2,-1)]

    for a, b in existing:
        for dx, dy in directions:
            x = a + dx
            y = b + dy
            if 1 <= x <= n and 1 <= y <= n:
                s.add((x, y))

    c = 0
    for a, b in existing:
        if (a, b) in s:
            c += 1

    total_forbidden = len(s) + m - c
    ans = n * n - total_forbidden
    print(ans)

if __name__ == "__main__":
    main()
