        if array[i] > array[i + 1]:
            inversions.append(i)
    # Check if there's exactly one inversion
    if len(inversions) != 1:
        print("No")
    else:
        # Swap the elements at the inversion position and check
        i = inversions[0]
        temp = array.copy()
        temp[i], temp[i + 1] = temp[i + 1], temp[i]
        if temp == sorted_arr:
            print("Yes")
        else:
            print("No")
